import MainCards from "../components/MainCards";

function Home() {
  return (
    <>
      <MainCards
        title="Fitness Products"
        data={cardsFitness}
        buttonLink="/fitness"
      />

      <MainCards
        title="Supplements"
        data={cardsSupplements}
        buttonLink="/supplements"
      />

      <MainCards
        title="Body Care"
        data={cardsBodyCare}
        buttonLink="/bodycare"
      />
    </>
  );
}

export default Home;
